import React, { useState, useEffect } from "react";
import CustomerBlock from "./components/CustomerBlock";
import AssignmentResult from "./components/AssignmentResult";
import ErrorBoundary from "./components/ErrorBoundary";
import "./App.css";

const API_FETCH_CUSTOMERS = process.env.REACT_APP_API_URL_CUSTOMERS;
const API_FETCH_STORAGES = process.env.REACT_APP_API_URL_STORAGES;
const API_FETCH_CATALOGS = process.env.REACT_APP_API_URL_CATALOGS;
const API_ASSIGN_TRUCKS = process.env.REACT_APP_API_ASSIGN_TRUCKS;

function App() {
  const [customers, setCustomers] = useState([]);
  const [storages, setStorages] = useState([]);
  const [categories, setCategories] = useState([]);
  const [customerBlocks, setCustomerBlocks] = useState([]);
  const [assignedVehicles, setAssignedVehicles] = useState([]);

  useEffect(() => {
    fetch(API_FETCH_CUSTOMERS)
      .then(res => res.json())
      .then(data => setCustomers(data.customers));

    fetch(API_FETCH_STORAGES)
      .then(res => res.json())
      .then(data => setStorages(data.storages));

    fetch(API_FETCH_CATALOGS)
      .then(res => res.json())
      .then(data => setCategories(data.catalogs));
  }, []);

  const handleSubmit = async () => {
    const orders = [];
    customerBlocks.forEach(block => {
      block.products.forEach(p => {
        orders.push({
          CustomerID: block.customerId,
          productName: p.name,
          weight: parseFloat(p.weight),
          StorageID: p.storageId,
          offRoute: false
        });
      });
    });

    const response = await fetch(API_ASSIGN_TRUCKS, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ orders })
    });

    const result = await response.json();
    setAssignedVehicles(result.assigned_vehicles || []);
  };

  return (
    <div className="container">
      <header className="header">
        <h1>Assign Truck</h1>
        <button onClick={() => setCustomerBlocks([...customerBlocks, { id: Date.now(), customerId: "", products: [] }])}>
          + Add Customer
        </button>
      </header>

      <main>
        <ErrorBoundary>
          {customerBlocks.map((block, index) => (
            <CustomerBlock
              key={block.id}
              index={index}
              block={block}
              customers={customers}
              storages={storages}
              categories={categories}
              updateBlock={(newBlock) => {
                const updated = [...customerBlocks];
                updated[index] = newBlock;
                setCustomerBlocks(updated);
              }}
              removeBlock={() => setCustomerBlocks(customerBlocks.filter((_, i) => i !== index))}
            />
          ))}
        </ErrorBoundary>

        <button className="submit-btn" onClick={handleSubmit}>Submit</button>

        <AssignmentResult vehicles={assignedVehicles} />
      </main>
    </div>
  );
}

export default App;
